import{_ as t,c as a,o,ae as i}from"./chunks/framework.Cd-3tpCq.js";const m=JSON.parse('{"title":"Delete Role (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"gql","title":"Delete Role","query":"mutation DeleteRole($input: deleteAdminSettingsRoleInput!) {\\n  deleteAdminSettingsRole(input: $input) {\\n    adminSettingsRole {\\n      id\\n      _id\\n      name\\n      description\\n      permissionType\\n      permissions\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/settings/roles/146\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminSettingsRole\\": {\\n      \\"adminSettingsRole\\": {\\n        \\"id\\": \\"/api/admin/settings/roles/146\\",\\n        \\"_id\\": 146,\\n        \\"name\\": \\"Seasonal Staff\\",\\n        \\"description\\": \\"Temporary holiday team\\",\\n        \\"permissionType\\": \\"all\\",\\n        \\"permissions\\": null,\\n        \\"message\\": \\"Role deleted successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/settings/roles/delete.md","filePath":"api/graphql-api/admin/settings/roles/delete.md"}'),n={name:"api/graphql-api/admin/settings/roles/delete.md"};function s(l,e,r,d,p,c){return o(),a("div",null,e[0]||(e[0]=[i('<h1 id="delete-role-graphql" tabindex="-1">Delete Role (GraphQL) <a class="header-anchor" href="#delete-role-graphql" aria-label="Permalink to &quot;Delete Role (GraphQL)&quot;">​</a></h1><p>Deletes a role and returns a snapshot of the record that was removed, so you can confirm exactly what was deleted. The role no longer appears in the listing afterward.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>deleteAdminSettingsRole</code></td><td>Mutation</td><td>Delete a role</td></tr></tbody></table><h2 id="quirks" tabindex="-1">Quirks <a class="header-anchor" href="#quirks" aria-label="Permalink to &quot;Quirks&quot;">​</a></h2><ul><li><code>input.id</code> is the IRI form (<code>/api/admin/settings/roles/{id}</code>).</li><li>The mutation returns a snapshot of the just-deleted role — <code>id</code>, <code>_id</code>, <code>name</code>, <code>description</code>, <code>permissionType</code>, and <code>permissions</code> all resolve (a role with <code>permissionType: all</code> has <code>permissions: null</code>). The record itself is gone from the store.</li><li><code>message</code> carries the success confirmation (<code>Role deleted successfully.</code>). It resolves only on the delete result — it is <code>null</code> on list / detail / create / update.</li></ul><h2 id="guards" tabindex="-1">Guards <a class="header-anchor" href="#guards" aria-label="Permalink to &quot;Guards&quot;">​</a></h2><p>Deletion is refused (returns an <code>errors[]</code> message) when:</p><ul><li>The role is <strong>assigned to one or more admins</strong> — reassign those admins to a different role first.</li><li>It is the <strong>last remaining role</strong> — at least one role must always exist.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p></div>',10)]))}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
